mapper.select:
SELECT v.id, v.user_id, u.username, u.building, u.room_no, v.visitor_name, v.car_no, v.visit_date, v.time_start, v.time_end, v.status, v.enter_time, v.leave_time, v.create_time FROM visitor v JOIN `user` u ON u.id = v.user_id
AND v.visit_date >= #{fromDate}
ORDER BY v.visit_date ASC, v.time_start ASC, v.id ASC
